for i,(name,rate,size,speed,opacity,color) in enumerate([('distant',26,.0022,.10,.35,'#72848e'),('middle',16,.0035,.19,.5,'#a6b5bd'),('near',7,.005,.32,.65,'#dde4e5')]):
 if '--readable' in sys.argv: size*=2.8
