 e={'id':name+'-flakes','name':name,'enabled':True,'start':0,'end':4,'rate':rate,'burst':0,'capacity':128,'origin':{'x':0,'y':-.25,'z':0},'spawn':{'shape':'box','width':2.1,'height':1.25,'depth':0,'radius':0},'particle':p}
